/**
 * Dockerfile of Kong's collector sidecar: the pinned contrib distribution
 * with the environment's config (config.yaml in the build context)
 */

import {
  KONG_COLLECTOR_BASE_IMAGE,
  KONG_COLLECTOR_CONFIG_PATH,
} from '../../constants';

export function buildKongCollectorDockerfile(): string {
  return `# Kong's OpenTelemetry Collector sidecar
# Generated by: npx tsdevstack infra:build-kong
FROM ${KONG_COLLECTOR_BASE_IMAGE}
COPY config.yaml ${KONG_COLLECTOR_CONFIG_PATH}
`;
}
